  ∀ ξ : Fin x.1 → (Weil h →* ℂˣ), (∀ t : Ine (F := E) A, y.charPol (ineIncl h t) = ∏ j, (X - C ((ξ j (ineIncl h t) : ℂˣ) : ℂ))) →
    Toral x

